const zone = 'America/Sao_Paulo';
const item = $input.first().json;
const body = (item.body && typeof item.body === 'object') ? item.body : {};
const query = (item.query && typeof item.query === 'object') ? item.query : {};
const url = String(item.webhookUrl || '').toLowerCase();

const DOCS = {
  compra:   'ID_PLANILHA_COMPRA',
  blog:     'ID_PLANILHA_BLOG',
  whatsapp: 'ID_PLANILHA_WHATSAPP',
  amostra:  'ID_PLANILHA_AMOSTRA',
  youtube:  'ID_PLANILHA_YOUTUBE'
};

let origem = '';
if (url.indexOf('compra-fauth') > -1) origem = 'compra';
else if (url.indexOf('materiais-youtube-fauth') > -1) origem = 'youtube';
else if (url.indexOf('blog-fauth') > -1) origem = 'blog';
else if (url.indexOf('whatsapp-fauth') > -1) origem = 'whatsapp';
else if (url.indexOf('amostra-fauth') > -1) origem = 'amostra';
if (!origem) throw new Error('Webhook de origem desconhecida: ' + url);

const UTM_KEYS = ['utm_source','utm_medium','utm_campaign','utm_content','utm_term','utm_creative_format','gclid','fbclid'];

const kv = {};
const add = (k, v) => {
  if (k === undefined || k === null) return;
  const key = String(k).trim().toLowerCase();
  if (!key) return;
  let val = v;
  if (val && typeof val === 'object') {
    if ('value' in val) val = val.value; else val = JSON.stringify(val);
  }
  if (Array.isArray(val)) val = val.join(', ');
  kv[key] = (val === undefined || val === null) ? '' : String(val);
};
const absorve = (obj) => {
  if (!obj) return;
  if (Array.isArray(obj)) {
    for (const e of obj) { if (e && typeof e === 'object') add(e.key !== undefined ? e.key : (e.id !== undefined ? e.id : e.name), e.value !== undefined ? e.value : ''); }
  } else if (typeof obj === 'object') {
    for (const [k, v] of Object.entries(obj)) {
      if ((k === 'fields' || k === 'values' || k === 'form_fields') && v && typeof v === 'object') { absorve(v); }
      else add(k, v);
    }
  }
};
absorve(body);
absorve(query);

const usadas = new Set();
const achaPorChave = (regex) => {
  for (const k of Object.keys(kv)) {
    if (usadas.has(k)) continue;
    if (regex.test(k)) { usadas.add(k); return kv[k]; }
  }
  return '';
};

let email = '';
for (const k of Object.keys(kv)) {
  const v = kv[k];
  if ((/mail/.test(k) || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) && /@/.test(v)) { email = v; usadas.add(k); break; }
}

let telefone = achaPorChave(/(tel|phone|whats|celular|fone)/);
if (!telefone) {
  for (const k of Object.keys(kv)) {
    if (usadas.has(k)) continue;
    const v = kv[k];
    const d = v.replace(/\D/g, '');
    if (d.length >= 10 && d.length <= 14 && /^[\d\s()+.\-]+$/.test(v)) { telefone = v; usadas.add(k); break; }
  }
}
let dig = String(telefone || '').replace(/\D/g, '').replace(/^0+/, '');
if (dig) {
  if (dig.indexOf('55') === 0 && (dig.length === 12 || dig.length === 13)) telefone = dig;
  else if (dig.length === 10 || dig.length === 11) telefone = '55' + dig;
  else telefone = dig;
} else {
  telefone = '';
}

let nomeCompleto = '';
for (const k of Object.keys(kv)) {
  if (usadas.has(k)) continue;
  if (/(^|[_\s-])(nome|name|first)/.test(k) && !/form/.test(k) && !/(sobrenome|last)/.test(k)) { nomeCompleto = kv[k]; usadas.add(k); break; }
}
let sobrenome = achaPorChave(/(sobrenome|last[_\s-]?name|surname)/);
let primeiroNome = nomeCompleto;
if (!sobrenome && nomeCompleto.indexOf(' ') > -1) {
  const partes = nomeCompleto.trim().split(/\s+/);
  primeiroNome = partes.shift();
  sobrenome = partes.join(' ');
}

let pagina = '';
for (const cand of [kv['pagina'], kv['page_url'], kv['referer'], kv['referrer'], kv['url']]) {
  if (cand && /^https?:\/\//.test(cand)) { pagina = cand; break; }
}

const utms = {};
for (const uk of UTM_KEYS) {
  if (kv[uk]) { utms[uk] = kv[uk]; usadas.add(uk); }
}
if (pagina) {
  try {
    const parsed = new URL(pagina);
    for (const uk of UTM_KEYS) {
      const qv = parsed.searchParams.get(uk);
      if (!utms[uk] && qv) utms[uk] = qv;
    }
  } catch (e) {}
}

const agora = DateTime.now().setZone(zone);

const linha = {
  'Data': agora.toFormat('dd/LL/yyyy'),
  'Hora': agora.toFormat('HH:mm:ss'),
  'Status': kv['status'] || '',
  'Formulario': kv['formulario'] || kv['form_name'] || kv['form'] || '',
  'Foco': kv['foco'] || kv['foco_de_estudos'] || '',
  'Estado': kv['estado'] || kv['uf'] || '',
  'primeiro_nome': primeiroNome || '',
  'sobrenome': sobrenome || '',
  'email': email || '',
  'telefone': telefone,
  'or': kv['or'] || kv['origem'] || '',
  'utm_source': utms.utm_source || '',
  'utm_medium': utms.utm_medium || '',
  'utm_campaign': utms.utm_campaign || '',
  'utm_content': utms.utm_content || '',
  'utm_term': utms.utm_term || '',
  'utm_creative_format': utms.utm_creative_format || '',
  'gclid': utms.gclid || '',
  'fbclid': utms.fbclid || '',
  'pagina': pagina,
  'video': kv['video'] || kv['video_url'] || '',
  '_docId': DOCS[origem],
  '_origem': origem
};

return [{ json: linha }];
